package run.ikaros.finance; import java.util.UUID; import org.springframework.data.repository.reactive.ReactiveCrudRepository; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono; public interface BalanceSnapshotRepository extends ReactiveCrudRepository<BalanceSnapshotEntity,UUID>{Flux<BalanceSnapshotEntity> findAllByLedgerIdAndOwnerIdOrderBySnapshotDateDesc(UUID ledgerId,UUID ownerId);Mono<BalanceSnapshotEntity> findByAccountIdAndOwnerIdAndSnapshotDate(UUID accountId,UUID ownerId,java.time.LocalDate snapshotDate);Flux<BalanceSnapshotEntity> findAllByLedgerIdOrderBySnapshotDateDesc(UUID ledgerId);Mono<BalanceSnapshotEntity> findByAccountIdAndSnapshotDate(UUID accountId,java.time.LocalDate snapshotDate);}
